 guest(id){const key=normalizeId(id);return this.s.guests.find(g=>g.id===key||g.aliases?.includes(key));}
 addGuest({id,name,avatar='',role='viewer',aliases=[]}){if(this.s.phase!=='lobby'&&!(this.s.phase==='paused'&&this.s.admission.open)&&!(this.s.admission.entryMode==='comment'&&this.canAdmit()))throw Error('برای تغییر فهرست، دور جدید بسازید');id=normalizeId(id);if(!/^[a-z0-9._-]{1,64}$/.test(id)||!String(name||'').trim())throw Error('نام و شناسه را وارد کنید');if(this.guest(id))throw Error('این شناسه قبلاً ثبت شده است');if(this.s.guests.length>=52)throw Error('حداکثر ۵۲ نفر');this.s.guests.push({id,name:String(name).trim().slice(0,50),avatar,role,aliases:[...new Set(aliases.map(normalizeId).filter(x=>x&&x!==id))],coins:0});return id;}
 removeGuest(id){if(this.s.phase!=='lobby')throw Error('در دور فعال فهرست ثابت است');this.s.guests=this.s.guests.filter(g=>g.id!==id);}
 saveSettings(values={}){const before=this.snapshot();try{if(values.narrationLanguage!==undefined){if(!['fa','en'].includes(values.narrationLanguage))throw Error('زبان گوینده معتبر نیست');this.s.audio??={};this.s.audio.narrationLanguage=values.narrationLanguage;this.s.language=values.narrationLanguage;}const presentation={},admission={},config={};for(const k of ['motionSeconds','revealSeconds','arrivalSeconds'])if(values[k]!==undefined)presentation[k]=values[k];for(const k of ['autoArrival','style','funLayout','leagueSeconds','leagueDemo','leagueIdleSeconds','leagueAutoStart','leagueVoice'])if(values[k]!==undefined)presentation[k]=values[k];for(const [from,to]of [['entryMode','entryMode'],['maxPlayers','maxPlayers'],['registrationSeconds','seconds'],['minGiftCoins','minCoins']])if(values[from]!==undefined&&(from==='entryMode'?values[from]:Number(values[from]))!==this.s.admission[to])admission[to]=values[from];if(values.revealMode!==undefined&&values.revealMode!==this.s.revealMode)config.revealMode=values.revealMode;if(values.autoMode!==undefined&&values.autoMode!==this.s.auto)config.auto=values.autoMode;if(Object.keys(admission).length)this.configureAdmission(admission);if(Object.keys(config).length)this.configure(config);this.presentationSettings(presentation);if(['profileRetentionMode','profileNewSeconds','profileActiveSeconds'].some(k=>values[k]!==undefined))this.configureProfileRetention(values);}catch(e){this.restore(before);throw e;}}
 configure({revealMode,auto,catalog}={}){if(this.s.phase!=='lobby')throw Error('تنظیمات را پیش از شروع انجام دهید');if(revealMode)this.s.revealMode=revealMode==='batch'?'batch':'immediate';if(typeof auto==='boolean')this.s.auto=auto;if(catalog){if(catalog.length!==52||catalog.some(g=>!g.name||!Number.isSafeInteger(g.coins)||g.coins<1))throw Error('برای هر ۵۲ خانه نام و امتیاز مثبت لازم است');this.s.catalog=catalog.map(g=>({...g}));}}
 configureAdmission({maxPlayers,seconds,minCoins,entryMode}={}){const a=this.s.admission;if(a.running)throw Error('ابتدا تایمر را توقف دهید');if(entryMode==='gift')throw Error('ورود با گیفت غیرفعال است؛ بازی رایگان است');if(entryMode!==undefined){if(!['gift','comment'].includes(entryMode))throw Error('روش ورود معتبر نیست');a.entryMode=entryMode;}if(minCoins!==undefined){minCoins=Number(minCoins);if(!Number.isInteger(minCoins)||minCoins<1||minCoins>1000000)throw Error('حداقل گیفت باید از 1 تا 1000000 کوین باشد');a.minCoins=0}if(maxPlayers!==undefined){maxPlayers=Number(maxPlayers);if(!Number.isInteger(maxPlayers)||maxPlayers<1||maxPlayers>52||maxPlayers<this.s.guests.length)throw Error('ظرفیت باید بین تعداد افراد فعلی و 52 باشد');a.maxPlayers=maxPlayers}if(seconds!==undefined){seconds=Number(seconds);if(!Number.isInteger(seconds)||seconds<0||seconds>3600)throw Error('زمان باید بین 0 و 3600 ثانیه باشد');a.seconds=seconds;a.remainingMs=seconds*1000}}
 canAdmit(){const s=this.s,free=s.admission.entryMode==='comment'&&s.mode==='main'&&s.phase==='playing'&&s.registrationOpen&&(!s.deadline||this.now()<s.deadline);return (free||(s.admission.open&&!s.admission.running&&['lobby','paused'].includes(s.phase)))&&s.guests.length<s.admission.maxPlayers;}
 admit(person){if(!this.canAdmit())throw Error('پذیرش بسته است یا ظرفیت بازی تکمیل شده');if(this.guest(person.id))return null;const id=this.addGuest(person);if(['paused','playing'].includes(this.s.phase)&&!this.s.eligible.includes(id))this.s.eligible.push(id);const cue={id:'join:'+id+':'+this.now(),guestId:id};this.s.joinQueue.push(cue);this.nextJoin(this.now());return id;}
 nextJoin(time){if(!this.s.joinReveal&&this.s.joinQueue.length)this.s.joinReveal={...this.s.joinQueue.shift(),startedAt:time,endsAt:time+JOIN_MS};}
 invite({id,code,name=''}){id=normalizeId(id);code=String(code).replace(/[۰-۹]/g,c=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(c))).replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).trim();if(!/^[a-z0-9._-]{1,64}$/.test(id)||!/^\d{1,4}$/.test(code))throw Error('یوزرنیم و کد عددی 1 تا 4 رقمی را وارد کنید');if(!this.s.admission.open||this.s.admission.running)throw Error('پذیرش بسته است');this.s.invites=this.s.invites.filter(x=>x.id!==id);this.s.invites.push({id,code:Number(code),name:String(name).trim().slice(0,50)});return true;}
 admitCode(person,comment){const code=String(comment).replace(/[۰-۹]/g,c=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(c))).replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).trim();if(!/^\d{1,4}$/.test(code)||!this.canAdmit()||this.guest(person.id))return null;const invite=this.s.invites.find(x=>x.id===normalizeId(person.id)&&x.code===Number(code));if(!invite)return null;const support=(this.s.supporters||[]).find(x=>x.id===normalizeId(person.id)||x.aliases?.includes(normalizeId(person.id)));if(this.s.admission.entryMode!=='comment'&&(!support||support.coins<this.s.admission.minCoins))return null;const id=this.admit({...person,name:invite.name||person.name});this.s.invites=this.s.invites.filter(x=>x!==invite);return id;}
 stop(){const s=this.s,a=s.admission;a.remainingMs=s.deadline?Math.max(0,s.deadline-this.now()):a.remainingMs;a.running=false;a.open=true;if(s.phase!=='lobby'&&s.phase!=='paused'){s.phase='paused';s.pausedAt=this.now();s.registrationOpen=false;s.deadline=null;}s.notice='تایمر متوقف است؛ پذیرش نفر جدید باز است.';}
