 profileClock(command,seconds,time=this.now()){const r=this.profileRound();if(command==='auto'){r.autoStart=seconds===true;r.manualPaused=false;if(r.autoStart&&r.phase==='ready')return this.profileClock('start',undefined,time);return true;}if(command==='duration'){const n=Number(seconds);if(!Number.isInteger(n)||n<15||n>3600)throw Error('زمان باید از 15 تا 3600 ثانیه باشد');if(r.phase==='playing')throw Error('برای تغییر زمان، اول تایمر را توقف دهید');r.seconds=n;r.remainingMs=n*1000;r.deadline=null;return true;}if(command==='pause'){if(r.phase!=='playing')return false;if(time>=r.deadline)return this.profileClock('finish',undefined,time);r.remainingMs=Math.max(0,r.deadline-time);r.deadline=null;r.phase='paused';r.manualPaused=true;return true;}if(command==='reset'){this.s.fun.profileAttract=null;this.s.fun.lastProfileActivityAt=time;if(this.s.fun.battleMode78)arenaReset(this.s.fun,time);r.phase='ready';r.questionIndex=null;r.quizKey=null;r.manualPaused=true;r.remainingMs=r.seconds*1000;r.deadline=null;r.members=[];r.quizResponses=[];r.chartMembers=this.profileChartSeed();if(!r.chartMembers.some(m=>m.id===r.chartThroneId))r.chartThroneId=r.chartMembers[0]?.id||null;r.throneId=null;r.winner=null;r.finishedAt=null;return true;}if(command==='start'){if(r.phase==='playing')return false;const resume=r.phase==='paused';if(!resume)r.quizEpoch=(r.quizEpoch||0)+1;r.manualPaused=false;if(r.phase==='finished'){r.number++;r.quizResponses=[];r.members=[];r.quizResponses=[];r.chartMembers=this.profileChartSeed();if(!r.chartMembers.some(m=>m.id===r.chartThroneId))r.chartThroneId=r.chartMembers[0]?.id||null;r.throneId=null;r.winner=null;r.finishedAt=null;r.remainingMs=r.seconds*1000;}r.remainingMs??=r.seconds*1000;r.deadline=time+r.remainingMs;r.phase='playing';if(this.s.fun.battleMode78&&!resume)arenaReset(this.s.fun,time);this.rotateQuiz(time);return true;}if(command==='finish'){if(!['playing','paused'].includes(r.phase))return false;r.phase='finished';r.finishedAt=time;r.remainingMs=0;r.deadline=null;r.winner=[...r.members].map(p=>({...p})).filter(p=>p.points>0&&this.s.fun.people.some(person=>person.id===p.id&&bubbleLife(person,time)==='active')).sort((a,b)=>b.points-a.points||(b.id===r.throneId?1:0)-(a.id===r.throneId?1:0)||a.lastActivityAt-b.lastActivityAt)[0]||null;if(r.winner)r.winner.tied=r.members.filter(m=>m.points===r.winner.points&&this.s.fun.people.some(p=>p.id===m.id&&bubbleLife(p,time)==='active')).length>1;if(this.s.fun.battleMode78){r.resultMembers=arenaRankings(this.s.fun,time).slice(0,3).map(p=>({...p}));r.winner=r.resultMembers[0]||null;arenaReset(this.s.fun,time);}return true;}throw Error('فرمان تایمر معتبر نیست');}
 profileTick(time=this.now()){const existed=!!this.s.fun.profileRound;const thanksChanged=this.profileSupportThanksTick(time);const r=this.profileRound();if(r.phase==='playing'&&time>=r.deadline)return this.profileClock('finish',undefined,time);if(r.autoStart&&!r.manualPaused&&(r.phase==='ready'||r.phase==='finished'&&time>=r.finishedAt+10000))return this.profileClock('start',undefined,time);const f=this.s.fun;f.lastProfileActivityAt??=time;let changed=!existed||thanksChanged;if(r.phase==='playing'&&this.rotateQuiz(time))changed=true;const slot=quizState(r,time).slot;if(r.questionSlot!==slot){r.questionSlot=slot;changed=true;}if(time-f.lastProfileActivityAt>=20000&&!f.profileAttract){f.profileAttract={startedAt:time};changed=true;}return changed;}


 refreshFun(){if(this.s.fun.layout==='football'){const l=leagueState(this.s.fun);l.previews=[];l.active=null;this.fillFunQueue();return;}this.s.fun.people=[];this.s.fun.profileIntros=[];this.s.fun.active=null;this.fillFunQueue();}
 clearFunCard(number){number=Number(number);if(this.s.fun.layout==='football'){const l=leagueState(this.s.fun);l.previews=l.previews.filter(x=>x.number!==number);if(l.active?.number===number)l.active=null;this.fillFunQueue();return;}if(!Number.isInteger(number)||number<1||number>52)throw Error('عدد باید از 1 تا 52 باشد');const person=this.s.fun.people.find(x=>x.number===number);this.s.fun.people=this.s.fun.people.filter(x=>x.number!==number);if(person&&this.s.fun.active?.personId===person.id)this.s.fun.active=null;this.fillFunQueue();}
 clearFunQueue(){if(this.s.fun.layout==='football')leagueState(this.s.fun).queue=[];else this.s.fun.queue=[];}
 remixValues(time=this.now()){const s=this.s,remix=(deck,locked)=>{if(!deck?.length)return;const free=deck.map((gift,i)=>({gift,i})).filter(x=>!locked.has(x.i+1)),gifts=shuffle(free.map(x=>x.gift),this.rnd);free.forEach((x,i)=>deck[x.i]=gifts[i]);};if(s.mode==='tie'){for(const [id,deck]of Object.entries(s.personalDecks))remix(deck,new Set(s.picks.filter(p=>p.guestId===id).map(p=>p.number)));}else remix(s.deck,new Set([...s.picks.map(p=>p.number),...Object.keys(s.hostOpened||{}).map(Number)]));s.valueRevision=(s.valueRevision||0)+1;s.nextShuffleAt=time+20000;}
 mix(){const s=this.s;const numbers=shuffle(Array.from({length:52},(_,i)=>({n:i+1})),this.rnd);s.boardOrder=numbers.map(x=>x.n);const remap=(deck,locked)=>{if(deck.length!==52)return;const free=deck.map((gift,i)=>({gift,i})).filter(x=>!locked.has(x.i+1));const gifts=shuffle(free.map(x=>x.gift),this.rnd);free.forEach((x,i)=>deck[x.i]=gifts[i]);};if(s.mode==='tie'){for(const [id,deck]of Object.entries(s.personalDecks))remap(deck,new Set(s.picks.filter(p=>p.guestId===id).map(p=>p.number)));}else {const locked=new Set([...s.picks.map(p=>p.number),...Object.keys(s.hostOpened||{}).map(Number)]);remap(s.deck,locked);if(s.hostDeck)remap(s.hostDeck,locked);}s.mixCount=(s.mixCount||0)+1;return true;}
 reset(){const {guests,catalog,revealMode,auto,seen,language,supporters,supporterSeen,catalogVersion,admission,viewMode,presentation,fun,arrivals,liveHost}=this.s;const fresh=new Game({randomInt:this.rnd,now:this.now});this.s=fresh.s;Object.assign(this.s,{guests,catalog:catalogVersion==='paired-five-tiers-v2'?catalog:GIFTS.map(g=>({...g})),revealMode,auto,seen,language,supporters,supporterSeen,admission:{...admission,open:true,running:false,remainingMs:admission.seconds*1000},viewMode,presentation,fun,arrivals,liveHost});}
 gift({userId,coins,eventId}){const g=this.guest(userId);coins=Number(coins);if(!g||!Number.isSafeInteger(coins)||coins<1||coins>1000000||this.seen(eventId))return false;g.coins+=coins;return true;}
